const resource_guard = if resource_fail_fast {
        __intra_turn_resource_guard(call, tools, options)
      } else {
        nil
      }

const settled = parallel settle indexed with { max_concurrent: cap } { entry ->
    __invoke_tool_with_index(harness, entry.call, entry.index, tools, options)
  }

__agent_loop_with_llm_render_context(
    harness,
    opts,
    { render_harness, effective ->
      const fragments = agent_build_turn_system_fragments(
        render_harness,
        session,
        effective,
        iteration,
      )
      let parts = []
      for fragment in fragments {
        parts = parts.appending(fragment.body)
      }
      return {
        fragments: fragments,
        system: join(parts, "\n\n"),
        messages: agent_build_turn_messages(
          render_harness.agent,
          render_harness.clock,
          session,
          effective,
          iteration,
        ),
      }
    },
  )

const llm_opts = __agent_loop_effective_llm_options(harness.llm, wrapup_opts)
    + {
      messages: turn_messages,
      session_id: session.session_id,
      tool_format: wrapup_opts?.tool_format,
      tools: nil,
      _iteration: iteration + 1,
      _final_wrapup: true,
      _call_stage: "wrapup",
    }

const repair_opts = __agent_loop_effective_llm_options(
    harness.llm,
    opts + {_output_contract_repair: true},
  )
    + {
      session_id: session.session_id,
      tools: nil,
      tool_choice: nil,
      tool_format: opts?.tool_format,
      _iteration: iteration + 1,
      _output_contract_repair: true,
      _call_stage: "repair",
    }

const user_budget = if type_of(raw) == "string" {
    {mode: raw}
  } else {
    raw
  }

const instruction = if native_mode {
      "Call `"
        + to_string(tool_name)
        + "` now using the available native tool interface. Do not describe the action again."
    } else {
      // The exemplar is the bare call envelope and carries no argument values.
      // It used to carry a type placeholder per required argument; a model
      // copied that token into the repair call and then into every call for
      // the rest of the session. Inside a JSON string a placeholder is
      // indistinguishable from a value, so what the call needs is said in
      // prose, from the tool's own declared required parameters.
      "Emit the call now: "
        + agent_render_tool_call_exemplar(harness.llm, to_string(tool_name), [], opts)
        + " Fill in the argument values this call needs and leave out the ones it does not."
        + __required_argument_sentence(
          to_string(tool_name),
          tool_required_argument_names(opts?.tools, tool_name),
        )
        + " Do not describe the action again."
    }

const narrowing = if contains(successful_tool_names, "load_skill") {
    {history: [], narrowed_tools: nil, changed: false}
  } else {
    __tool_surface_narrowing_post_turn(harness.agent, session, llm_result, dispatch_results, opts)
  }

const payload = {
    session_id: session.session_id,
    stall_checkpoint: opts?._stall_checkpoint,
    session: {id: session.session_id},
    iteration: iteration,
    has_tool_calls: has_tool_calls,
    dispatch: dispatch,
    tool_results: dispatch_results,
    tool_count: len(dispatch_results),
    tool_names: tool_names,
    tools: opts?.tools,
    available_tool_names: __tool_surface_current_names(opts),
    claimable_tool_names: __tool_surface_claimable_names(opts),
    provider: opts?.provider,
    model: opts?.model,
    tool_format: opts?.tool_format,
    successful_tool_names: successful_tool_names,
    rejected_tool_names: rejected_tool_names,
    session_successful_tools: opts?._session_successful_tools ?? successful_tool_names,
    session_rejected_tools: opts?._session_rejected_tools ?? rejected_tool_names,
    // The corrective claimed the PREVIOUS turn for repair, so this turn is the
    // repair attempt it asked for. Host control policies that classify a
    // toolless turn as churn read this to tell "the model is spinning" from
    // "the loop asked for exactly one more turn and this is it", instead of
    // inferring it from ordering they cannot see.
    prior_turn_claimed_for_repair: opts?._next_tool_claim?.source
      == "missing_tool_call_recovery",
    prior_turn_next_tool_claim: opts?._next_tool_claim,
    text: text,
    visible_text: text,
    // `text`/`visible_text` are the PROJECTION: the parser has already removed
    // completion markers and structural tags from them. Anything deciding
    // whether the model declared completion must read `raw_text` instead —
    // it is the same string the sentinel detector below reads, so host
    // completion checks and the loop's own detector cannot disagree about
    // what the turn said. Projection is for display; raw is for semantics.
    raw_text: sentinel_text,
    parsed_done_marker: parsed_done_marker,
  }

const repaired = if loop_continues {
    __maybe_inject_action_nudge(harness, session, opts, false, text, iteration)
  } else {
    nil
  }

const base = if type_of(options) == "dict" {
    options
  } else {
    {}
  }

loop_until_done_system_prompt(
    fs,
    completion
      + {
        loop_until_done: loop_until_done,
        exit_when_verified: opts?.exit_when_verified ?? false,
        has_tools: agent_has_tools(opts),
        calls_label: paradigm.call_noun + "s",
        sentinel_active: sentinel != nil,
        // Compatibility for prompt overrides written before the stable
        // `done_sentinel_form` binding. The decision still comes from the one
        // completion projection above.
        plain_text_done: completion.done_sentinel_form != "done_block",
      },
    opts,
  )

render_agent_prompt_id(
    fs,
    "agent.tool_contract_json",
    {
      done_sentinel: __agent_done_sentinel(opts),
      body_hint: agent_tool_call_paradigm(llm, opts).body_hint,
      expanded_schemas: __agent_tool_listing_prompt(opts.tools),
    },
    opts,
  )
